package agenthub

import("context";"strings";"testing";"time";"github.com/eutelic/runnerhub/internal/agent";"github.com/eutelic/runnerhub/internal/provider";"github.com/eutelic/runnerhub/internal/store")
func newTestHub(t *testing.T)(*Hub,store.Store){t.Helper();st,_:=store.OpenSQLite(":memory:");h,err:=New(st,"1234567890123456","12345678901234567890123456789012");if err!=nil{t.Fatal(err)};return h,st}
func TestCommandLeaseRedeliversAndAcks(t *testing.T){h,st:=newTestHub(t);defer st.Close();now:=time.Date(2026,8,9,0,0,0,0,time.UTC);h.now=func()time.Time{return now};h.lease=time.Minute;if err:=h.Enqueue("host-1",agent.Command{Type:agent.CommandDelete,WorkerID:"worker-1"});err!=nil{t.Fatal(err)};first:=h.Next("host-1");if len(first)!=1{t.Fatalf("first delivery=%d",len(first))};if got:=h.Next("host-1");len(got)!=0{t.Fatalf("leased command redelivered early: %d",len(got))};now=now.Add(2*time.Minute);again:=h.Next("host-1");if len(again)!=1||again[0].ID!=first[0].ID{t.Fatalf("expected same command after lease expiry: %#v",again)};calls:=0;h.SetResultHandler(func(context.Context,string,agent.CommandResult)error{calls++;return nil});res:=agent.CommandResult{CommandID:first[0].ID,WorkerID:"worker-1",OK:true};if err:=h.HandleResult(context.Background(),"host-1",res);err!=nil{t.Fatal(err)};if err:=h.HandleResult(context.Background(),"host-1",res);err!=nil{t.Fatal(err)};if calls!=1{t.Fatalf("result handler calls=%d",calls)};now=now.Add(2*time.Minute);if got:=h.Next("host-1");len(got)!=0{t.Fatalf("acked command redelivered: %d",len(got))}}
func TestCreateCommandEncryptsJITAtRestAndScrubsAfterAck(t *testing.T){h,st:=newTestHub(t);defer st.Close();secret:="sensitive-jit-config";cmd:=agent.Command{Type:agent.CommandCreate,WorkerID:"worker-secret",Spec:&provider.WorkerSpec{WorkerID:"worker-secret",JITConfig:secret}};if err:=h.Enqueue("host-1",cmd);err!=nil{t.Fatal(err)};leased,err:=st.LeaseCommands(context.Background(),"host-1",time.Now().UTC(),time.Now().UTC().Add(time.Minute),20);if err!=nil||len(leased)!=1{t.Fatalf("leased=%d err=%v",len(leased),err)};stored:=leased[0].Spec.JITConfig;if stored==secret||!strings.HasPrefix(stored,"enc:v1:"){t.Fatalf("jit was not encrypted at rest: %q",stored)};h.now=func()time.Time{return time.Now().UTC().Add(2*time.Minute)};delivered:=h.Next("host-1");if len(delivered)!=1||delivered[0].Spec==nil||delivered[0].Spec.JITConfig!=secret{t.Fatalf("decrypted delivery=%#v",delivered)};if err:=h.HandleResult(context.Background(),"host-1",agent.CommandResult{CommandID:delivered[0].ID,WorkerID:"worker-secret",OK:true});err!=nil{t.Fatal(err)};rec,err:=st.GetCommand(context.Background(),delivered[0].ID);if err!=nil{t.Fatal(err)};if rec.Command.Spec!=nil{t.Fatal("acked command retained sensitive spec")}}
